        # At least two Worker generations (revise and complete delivery) and a
        # real independent review must remain possible. Actual admission still
        # checks every full request and all original cumulative/cost limits.
        worker_floor = (
            len(
                _json(
                    {
                        "messages": initial,
                        "tools": self.manager.tools.definitions(allowed),
                        "model": row["model_id"],
                    }
                ).encode("utf-8")
            )
            + min(row["output_limit"], row["model_max_output_tokens"])
            + 128
