                        for item in errors[:12]
                    ],
                    "revision_goals": [
                        f"Correct JSON syntax in {item['path']} using only approved tools. Preserve prior receipt {item['receipt_id']} and expected SHA-256 {item['sha256']}; submit a new delivery."
                        for item in errors[:12]
                    ]
                    if repairable
                    else [],
                    "artifact_diagnostics": errors[:12],
                    "confidence": 1.0,
                },
            )
            work.append_event(event)
        if repairable:
            try:
                self.manager.request_revision(row["id"], event.id)
            except DomainError:
                return {**event.payload, "revision_applied": False}
            return {**event.payload, "revision_applied": True}
        return {**event.payload, "revision_applied": False}

    def _settle_usage(self, row, started, usage, maximum, price, cost_ledger):
        if not isinstance(usage, dict):
            return False
        inp, out = usage.get("input_tokens"), usage.get("output_tokens")
        reserve, cost_reserve = started["reserved_tokens"], started.get("reserved_cost_microunits")
        if (
            type(inp) is not int
            or type(out) is not int
            or inp < 0
            or out < 0
            or inp > reserve - maximum
            or out > maximum
        ):
            return False
        with self.store.unit_of_work() as work:
            released = work.connection.execute(
                "SELECT payload FROM events WHERE event_type='review.released' AND json_extract(payload,'$.call_id')=?",
                (started["call_id"],),
            ).fetchone()
            refunded = (
                released is not None and json.loads(released[0]).get("reservation_refunded") is True
            )
            if refunded:
                work.connection.execute(
                    "UPDATE worker_runs SET token_spent=token_spent+?,steps=steps+1 WHERE id=?",
                    (inp + out, row["id"]),
                )
                work.append_event(
                    ForgeEvent(
                        event_type="review.late_settlement",
                        quest_id=row["quest_id"],
                        worker_id=row["worker_id"],
                        payload={
                            "plan_id": row["plan_id"],
                            "task_node_key": row["node_key"],
                            "run_id": row["id"],
                            "call_id": started["call_id"],
                            "actual_tokens": inp + out,
                            "execution_mode": row["execution_mode"],
                        },
                    )
                )
            else:
                work.connection.execute(
                    "UPDATE worker_runs SET token_spent=token_spent-?+? WHERE id=?",
                    (reserve, inp + out, row["id"]),
                )
            if cost_reserve is not None:
                actual = (
                    inp * price["input_microunits_per_million"]
                    + out * price["output_microunits_per_million"]
                    + 999999
                ) // 1000000
                refund = -actual if refunded else cost_reserve - actual
                if refund < 0 and not refunded:
                    raise DomainError("Independent review cost exceeds reservation")
                work.connection.execute(
                    "UPDATE worker_runs SET cost_spent_microunits=cost_spent_microunits-? WHERE id=?",
                    (refund, row["id"]),
                )
                for item in cost_ledger:
                    work.connection.execute(
                        "UPDATE worker_cost_ledger SET reserved_microunits=reserved_microunits-? WHERE scope=? AND scope_id=? AND currency=?",
                        (refund, item["scope"], item["scope_id"], item["currency"]),
                    )
        return True

    def _release(self, work, started, *, unsent, reason, refund=False, retry_delay=None):
        c = work.connection
        if c.execute(
            "SELECT 1 FROM events WHERE event_type='review.released' AND json_extract(payload,'$.call_id')=?",
            (started["call_id"],),
        ).fetchone():
            return
        if refund:
            c.execute(
                "UPDATE worker_runs SET token_spent=token_spent-?,steps=steps-1 WHERE id=?",
                (started["reserved_tokens"], started["run_id"]),
            )
            reserved_cost = started.get("reserved_cost_microunits")
            if reserved_cost is not None:
                run = c.execute(
                    "SELECT * FROM worker_runs WHERE id=?", (started["run_id"],)
        elif streaming:
            payload["stream_options"] = {"include_usage": True}
        if request.context_limit is not None:
            if type(request.context_limit) is not int or request.context_limit < 1:
                raise ProviderError("configuration")
            try:
                input_size = len(json.dumps(payload, ensure_ascii=False).encode("utf-8")) + 64
            except (TypeError, ValueError):
                raise ProviderError("configuration") from None
            if input_size + request.max_output_tokens > request.context_limit:
                raise ProviderError("context_exceeded")
        return payload

    def _usage(self, raw):
        raw = raw or {}
        if not isinstance(raw, dict):
            raise ProviderError("protocol_error")
        if self.config.kind == "anthropic":
            uncached = raw.get("input_tokens")
            cached = raw.get("cache_read_input_tokens")
            created = raw.get("cache_creation_input_tokens")
            values = (uncached, cached, created, raw.get("output_tokens"))
            if any(value is not None and (type(value) is not int or value < 0) for value in values):
                raise ProviderError("protocol_error")
            total = uncached + (cached or 0) + (created or 0) if isinstance(uncached, int) else None
            return {
                "input_tokens": total,
                "output_tokens": raw.get("output_tokens"),
                "cached_input_tokens": cached,
                "cache_creation_input_tokens": created,
            }
        details = raw.get("prompt_tokens_details") or {}
        if not isinstance(details, dict):
            raise ProviderError("protocol_error")
        inp, out = raw.get("prompt_tokens"), raw.get("completion_tokens")
        cached = details.get("cached_tokens")
        if self.config.kind == "deepseek" and cached is None:
            cached = raw.get("prompt_cache_hit_tokens")
        miss = raw.get("prompt_cache_miss_tokens") if self.config.kind == "deepseek" else None
        if (
            any(
                value is not None and (type(value) is not int or value < 0)
                for value in (inp, out, cached, miss)
            )
            or (inp is not None and cached is not None and cached > inp)
            or (
                inp is not None and cached is not None and miss is not None and cached + miss != inp
            )
        ):
            raise ProviderError("protocol_error")
        return {
            "input_tokens": inp,
            "output_tokens": out,
            "cached_input_tokens": cached,
            "cache_creation_input_tokens": None,
        }

    async def _read_json(self, response):
        chunks = bytearray()
        async with aclosing(response):
            async for chunk in response.aiter_bytes():
                chunks.extend(chunk)
                if len(chunks) > 8 * 1024 * 1024:
                    raise ProviderError("protocol_error")
        try:
            return json.loads(chunks)
        except (ValueError, UnicodeDecodeError):
            raise ProviderError("protocol_error") from None

    async def _sse_lines(self, response):
        buffer = bytearray()
        total = 0
        async for chunk in response.aiter_bytes():
            total += len(chunk)
            if total > 8 * 1024 * 1024:
                raise ProviderError("protocol_error")
            buffer.extend(chunk)
            while b"\n" in buffer:
                line, _, rest = buffer.partition(b"\n")
                buffer = bytearray(rest)
                if len(line) > 1024 * 1024:
                    raise ProviderError("protocol_error")
                try:
                    yield line.rstrip(b"\r").decode("utf-8")
                except UnicodeDecodeError:
                    raise ProviderError("protocol_error") from None
            if len(buffer) > 1024 * 1024:
                raise ProviderError("protocol_error")
        if buffer:
            raise ProviderError("protocol_error")

    def _cost(self, usage):
        cfg = self.config
        inp, out, cached = (
            usage["input_tokens"],
            usage["output_tokens"],
            usage["cached_input_tokens"],
        )
        if usage.get("cache_creation_input_tokens"):
