            return False
        inp, out = usage.get("input_tokens"), usage.get("output_tokens")
        if (
            type(inp) is not int
            or type(out) is not int
            or inp < 0
            or out < 0
            or inp > reserve - output_limit
            or out > output_limit
        ):
